  function renderServiceCard(service){const events=[...(service.events||[])].sort((a,b)=>new Date(b.at)-new Date(a.at));const next=service.status==='not_started'?'Start work':service.status==='in_progress'?'Complete work':'';const target=service.status==='not_started'?'In progress':'Completed';return `<article class="service-card ${service.status==='completed'?'is-completed':''}" data-service-id="${esc(service.id)}"><div class="service-card-head"><div><h4 class="service-item-title">${esc(service.title)}</h4><div class="service-item-meta"><span class="service-tag ${typeClass(service.type)}">${esc(service.type)}</span> · ${esc(service.estimate||'Estimate pending')}</div>${service.department?`<div class="department-routing">Department work plan · ${esc(service.department)}</div>`:''}</div><span class="status ${itemStatusClass(service.status)}"><i></i><span class="status-label">${itemStatusLabel(service.status)}</span></span></div><div class="service-item-details"><div><div class="detail-key">Estimated time</div><div class="detail-val">${esc(service.estimate||'To be assessed')}</div></div><div><div class="detail-key">Latest update</div><div class="detail-val">${events[0]?dateLabel(events[0].at):'No updates yet'}</div></div></div>${service.request?`<div class="service-item-request">${esc(service.request)}</div>`:''}<div class="service-item-actions">${next?`<button class="primary-button service-progress ${pendingConfirmId===service.id?'is-armed':''}" data-service-id="${esc(service.id)}">${pendingConfirmId===service.id?'Confirm':next} ${pendingConfirmId===service.id?'':'<span>→</span>'}</button><span class="inline-confirm ${pendingConfirmId===service.id?'':'hidden'}" id="confirm-${esc(service.id)}">Confirm status change to <b>${target}</b>? <button class="cancel-progress" data-service-id="${esc(service.id)}" aria-label="Cancel status change">Cancel</button></span>`:''}<button class="quiet-change change-status" data-service-id="${esc(service.id)}">Change status</button><button class="link-button service-note" data-service-id="${esc(service.id)}">＋ Add update</button></div>${service.migratedTo?`<div class="migrated-callout">Transferred to latest record <button class="jump-latest" data-record-id="${esc(service.migratedTo.recordId)}">Open latest record →</button></div>`:''}<div class="service-history"><div class="history-heading">Service timeline</div>${events.slice(0,service.showAllEvents?events.length:3).map(event=>`<div class="mini-event"><time>${dateLabel(event.at)}</time><div class="event-copy"><b>${esc(event.title)}</b>${event.note?`<small>${esc(event.note)}</small>`:''}</div></div>`).join('')}${events.length>3?`<button class="link-button show-history" data-service-id="${esc(service.id)}">${service.showAllEvents?'Show latest three':'View all '+events.length+' updates'}</button>`:''}</div></article>`;}
  function previousServices(record){return records.filter(source=>source.id!==record.id&&source.plate.toUpperCase()===record.plate.toUpperCase()).flatMap(source=>getItems(source).filter(service=>!service.migratedTo).map(service=>({source,service,lastUpdate:[...(service.events||[])].sort((a,b)=>new Date(b.at)-new Date(a.at))[0]?.at||source.updatedAt||source.createdAt}))).sort((a,b)=>new Date(b.lastUpdate)-new Date(a.lastUpdate));}
  function hasPreviousServices(record){return previousServices(record).length>0;}
  function renderDetail(){const record=selected();if(!record)return;$('#detailContent').innerHTML=`<div class="detail-hero"><div class="detail-photo">${record.photo?`<img src="${record.photo}" alt="${esc(record.plate)}">`:'⌁'}</div><div><div class="detail-plate">${esc(record.plate)}</div><div class="detail-car">${esc(record.vehicle||'Vehicle details pending')}</div><div class="detail-client">${esc(record.customer||'Customer not listed')}${record.phone?` · ${esc(record.phone)}`:''}${record.email?` · ${esc(record.email)}`:''}</div><div class="customer-code-chip">Customer code <b>${esc(record.customerCode||'Pending')}</b>${record.customerCode?`<button type="button" class="copy-staff-customer-code" data-copy-code="${esc(record.customerCode)}">Copy code</button>`:''}</div><div style="margin-top:9px"><span class="status ${itemStatusClass(overallStatus(record))}"><i></i><span class="status-label">${itemStatusLabel(overallStatus(record))}</span></span></div><div class="record-maintenance"><button class="quiet-change" id="editVehicleDetails">Edit vehicle details</button><button class="danger-text-button" id="deleteVehicleRecord">Delete record</button></div></div></div><div class="detail-sections"><div class="detail-section-heading"><div><h3 class="section-title" style="margin:0">Service details <span class="total-count">${getItems(record).length}</span></h3><span class="detail-key">Each service has its own status and history</span></div><div class="detail-section-actions"><button class="secondary-button" id="addServiceFromDetail">＋ Add service</button>${hasPreviousServices(record)?'<button class="quiet-change" id="resumeServiceFromDetail">↶ Continue previous service</button>':''}</div></div><div class="service-card-list" style="margin-top:13px">${[...getItems(record)].sort(serviceSort).map(renderServiceCard).join('')}</div></div><div class="detail-sections"><h3 class="section-title">Vehicle and customer request</h3><div class="request-box">${esc(record.request||'No general handover notes added.')}</div><div class="detail-grid" style="margin-top:12px"><div><div class="detail-key">Checked in</div><div class="detail-val">${dateLabel(record.createdAt)}</div></div><div><div class="detail-key">Vehicle registration</div><div class="detail-val">${esc(record.plate)}</div></div></div></div>`;
    if(record.photo&&record.photoNotUpdated)$('#detailContent .detail-photo').insertAdjacentHTML('beforeend','<span class="photo-stale-badge">Photo not updated</span>');
    const linkedVehicles=customerVehicleRecords(record).filter(item=>overallStatus(item)!=='completed');if(linkedVehicles.length>1)$('#detailContent .detail-hero > div:last-child').insertAdjacentHTML('beforeend',`<button type="button" class="customer-vehicles-link" id="checkCustomerVehicles">Check all vehicles for this customer (${linkedVehicles.length})</button>`);
    $('#detailContent').insertAdjacentHTML('beforeend',renderSavedInspection());
    loadInspectionReports(record).then(reports=>{if(selectedId!==record.id)return;const panel=$('#inspectionReportsPanel');if(panel)panel.outerHTML=renderSavedInspection(reports);$$('.create-department-task',$('#detailContent')).forEach(button=>button.addEventListener('click',()=>createDepartmentTask(button.dataset.inspectionId,Number(button.dataset.recommendationIndex))));}).catch(error=>{console.error(error);const panel=$('#inspectionReportsPanel');if(panel)panel.innerHTML='<p class="inspection-review-note">Inspection reports could not be loaded.</p>';});
    $('#detailOverlay').classList.remove('hidden');
    $('#addServiceFromDetail').addEventListener('click',openExtraService);
    $('#editVehicleDetails').addEventListener('click',openEditVehicle);
    $('#deleteVehicleRecord').addEventListener('click',openDeleteConfirm);
    $('#resumeServiceFromDetail')?.addEventListener('click',openResumeService);
    $$('.service-progress', $('#detailContent')).forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.serviceId;if(pendingConfirmId===id){changeServiceProgress(id);return;}pendingConfirmId=id;renderDetail();}));
    $$('.cancel-progress', $('#detailContent')).forEach(button=>button.addEventListener('click',()=>{pendingConfirmId=null;renderDetail();}));
    $$('.change-status', $('#detailContent')).forEach(button=>button.addEventListener('click',()=>openStatusModal(button.dataset.serviceId)));
    $$('.service-note', $('#detailContent')).forEach(button=>button.addEventListener('click',()=>openServiceNote(button.dataset.serviceId)));
    $$('.show-history', $('#detailContent')).forEach(button=>button.addEventListener('click',()=>showFullHistory(button.dataset.serviceId)));
    $$('.jump-latest', $('#detailContent')).forEach(button=>button.addEventListener('click',()=>openDetail(button.dataset.recordId)));
  }
  function findService(serviceId){return getItems(selected()).find(service=>service.id===serviceId);}
  async function changeServiceProgress(serviceId){const record=selected(),service=findService(serviceId);if(!record||!service)return;pendingConfirmId=null;const at=nowISO(),next=service.status==='not_started'?'in_progress':'completed';transitionService(service,next,at);service.events.unshift({at,title:next==='in_progress'?'Work started':'Service completed',note:next==='in_progress'?'Service work has started.':'Service item marked complete.'});record.updatedAt=at;await saveRecord(record);await reload();renderDetail();toast(`${service.title}: ${itemStatusLabel(service.status)}`);}
  function openStatusModal(serviceId){const service=findService(serviceId);if(!service)return;const remainingMinutes=Math.max(0,Math.round((etaTimestamp(service)-Date.now())/60000));let unit='hours',amount=remainingMinutes/60;if(remainingMinutes%60){unit='minutes';amount=remainingMinutes;}else if(remainingMinutes>=1440&&remainingMinutes%1440===0){unit='days';amount=remainingMinutes/1440;}$('#statusServiceItemId').value=service.id;$('#statusServiceTitle').value=`${service.type} — ${service.title}`;$('#statusSelect').value=service.status;$('#statusNote').value='';$('#statusExpectedDuration').value=String(amount);$('#statusExpectedDurationUnit').value=unit;$('#detailOverlay').classList.remove('hidden');$('#statusOverlay').classList.remove('hidden');requestAnimationFrame(()=>$('#statusSelect').focus());}
  function openExtraService(){const record=selected();if(!record)return;$('#extraServiceForm').reset();$('#extraServiceVehicle').textContent=`${record.plate}${record.vehicle?` · ${record.vehicle}`:''}`;updateExtraServiceDefaults();$('#extraServiceOverlay').classList.remove('hidden');}
  function updateExtraServiceDefaults(){const type=$('#extraServiceType').value;$('#extraServiceItemTitle').value=defaultTitles[type]||'';$('#extraServiceEstimate').value=(parseEstimateMinutes(estimates[type])/60).toString();$('#extraServiceEstimateUnit').value='hours';}
  async function saveExtraService(event){event.preventDefault();const record=selected();if(!record)return;const type=$('#extraServiceType').value,title=$('#extraServiceItemTitle').value.trim(),minutes=estimateMinutesFromFields($('#extraServiceEstimate').value,$('#extraServiceEstimateUnit').value);if(!title)return toast('Add a title for this service item');if(!minutes)return toast('Enter an estimate greater than zero');const at=nowISO(),request=$('#extraServiceRequest').value.trim();record.services.push(makeServiceItem({type,title,estimate:durationText(minutes),request,at,events:[{at,title:'Service item added',note:request||'New service item added to the existing vehicle record.'}]}));record.updatedAt=at;await saveRecord(record);await reload();closeOverlay('extraServiceOverlay');renderDetail();toast('New service item added to this vehicle record');}
  function openResumeService(){const record=selected();if(!record)return;const options=previousServices(record);$('#resumeServiceVehicle').textContent=`${record.plate} · Choose a previous service to continue.`;$('#resumeServiceOptions').innerHTML=options.length?options.map(({source,service,lastUpdate})=>`<button type="button" class="resume-option" data-source-record="${esc(source.id)}" data-source-service="${esc(service.id)}"><span class="resume-option-main"><b>${esc(service.title)}</b><small><span class="service-tag ${typeClass(service.type)}">${esc(service.type)}</span> · Last updated ${dateLabel(lastUpdate)}</small><small>Previous record · ${dateLabel(source.createdAt)}</small></span><span class="resume-arrow">Continue →</span></button>`).join(''):'<div class="request-box">No previous services are available to continue.</div>';$('#resumeServiceOverlay').classList.remove('hidden');$$('.resume-option', $('#resumeServiceOptions')).forEach(button=>button.addEventListener('click',()=>resumePreviousService(button.dataset.sourceRecord,button.dataset.sourceService)));}
  async function resumePreviousService(sourceRecordId,sourceServiceId){const latest=selected(),source=records.find(record=>record.id===sourceRecordId),oldService=source&&getItems(source).find(service=>service.id===sourceServiceId);if(!latest||!source||!oldService||oldService.migratedTo)return toast('That previous service is no longer available');const at=nowISO(),newService={...oldService,id:makeId(),status:'not_started',migratedTo:null,migratedFrom:{recordId:source.id,serviceId:oldService.id},createdAt:at,updatedAt:at,startedAt:null,completedAt:null,actualDurationMinutes:0,workSessions:[],expectedCompletionAt:new Date(new Date(at).getTime()+(Number(oldService.estimateMinutes)||60)*60000),events:[...(oldService.events||[]).map(event=>({...event})),{at,title:'Service continued in latest vehicle record',note:`Previous service history copied from the ${dateLabel(source.createdAt)} vehicle record.`}]};latest.services.push(newService);latest.updatedAt=at;oldService.migratedTo={recordId:latest.id,serviceId:newService.id};oldService.events.unshift({at,title:'Transferred to latest record',note:`Service continued in the vehicle record created ${dateLabel(latest.createdAt)}.`});source.updatedAt=at;await saveRecord(source);await saveRecord(latest);await reload();closeOverlay('resumeServiceOverlay');openDetail(latest.id);toast('Previous service and its history were added to the latest vehicle record');}
  async function saveStatusChange(event){event.preventDefault();const record=selected(),service=findService($('#statusServiceItemId').value);if(!record||!service)return;const next=$('#statusSelect').value,note=$('#statusNote').value.trim(),minutes=estimateMinutesFromFields($('#statusExpectedDuration').value,$('#statusExpectedDurationUnit').value);if(!note)return toast('Add a short note explaining this update');if($('#statusExpectedDuration').value===''||!Number.isFinite(minutes))return toast('Enter a valid predicted completion duration');const previous=service.status,at=nowISO();transitionService(service,next,at,note);service.expectedCompletionAt=new Date(new Date(at).getTime()+minutes*60000).toISOString();service.estimateMinutes=minutes;service.estimate=durationText(minutes);service.events.unshift({at,title:previous===next?'Service update':`Status changed: ${itemStatusLabel(previous)} → ${itemStatusLabel(next)}`,note});record.updatedAt=at;await saveRecord(record);await reload();closeOverlay('statusOverlay');renderDetail();toast('Status and service history updated');}
  function openServiceNote(serviceId){const service=findService(serviceId);if(!service)return;$('#noteServiceItemId').value=service.id;$('#serviceNoteInput').value='';$('#noteModalSubtitle').textContent=`Add a note to “${service.title}” service history.`;$('#noteOverlay').classList.remove('hidden');requestAnimationFrame(()=>$('#serviceNoteInput').focus());}
  async function saveServiceNote(event){event.preventDefault();const service=findService($('#noteServiceItemId').value),record=selected(),note=$('#serviceNoteInput').value.trim();if(!service||!record||!note)return;const at=nowISO();service.events.unshift({at,title:'Progress update',note});service.updatedAt=at;record.updatedAt=at;await saveRecord(record);await reload();closeOverlay('noteOverlay');renderDetail();toast('Service update saved');}
  function openEditVehicle(){const record=selected();if(!record)return;$('#editPlate').value=record.plate||'';$('#editVehicle').value=record.vehicle||'';$('#editCustomer').value=record.customer||'';$('#editPhone').value=record.phone||'';$('#editPhotoFile').value='';$('#editPhotoHint').textContent=record.photo?'Choose an image to replace the current photo.':'No vehicle photo saved yet.';$('#editVehicleOverlay').classList.remove('hidden');}
  async function saveVehicleDetails(event){event.preventDefault();const record=selected();if(!record)return;const plate=$('#editPlate').value.trim().toUpperCase();if(records.some(item=>item.id!==record.id&&item.plate.toUpperCase()===plate&&overallStatus(item)!=='completed'))return toast('An active service record already uses this registration');record.plate=plate;record.vehicle=$('#editVehicle').value.trim();record.customer=$('#editCustomer').value.trim();record.phone=$('#editPhone').value.trim();const file=$('#editPhotoFile').files[0];if(file){if(!file.type.startsWith('image/'))return toast('Choose an image file');if(file.size>8*1024*1024)return toast('Photo must be 8 MB or smaller');record.photo=await photoData(file);record.photoNotUpdated=false;}record.updatedAt=nowISO();await saveRecord(record);await reload();closeOverlay('editVehicleOverlay');renderDetail();toast('Vehicle details updated');}
  function openDeleteConfirm(){const record=selected();if(!record)return;$('#deleteConfirmText').textContent=`${record.plate} · ${record.vehicle||'Vehicle details pending'} will be removed from active records and copied to the deleted database table.`;$('#deleteConfirmOverlay').classList.remove('hidden');}
  async function deleteSelectedRecord(){const record=selected();if(!record)return;const button=$('#confirmDeleteBtn');button.disabled=true;try{if(useLocalStorage){const database=await openLegacyDb();try{const tx=database.transaction([STORE,'deleted'],'readwrite');tx.objectStore('deleted').put({...record,deletedAt:nowISO()});tx.objectStore(STORE).delete(record.id);await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}finally{database.close();}}else{const {data,error}=await supabase.rpc('archive_service_record',{p_id:record.id});if(error)throw error;if(!data)throw new Error('The service record was not found and could not be archived.');}closeOverlay('deleteConfirmOverlay');closeOverlay('detailOverlay');selectedId=null;await reload();toast('Record moved to Deleted');}catch(error){toast(error.message||'Could not move this record to Deleted');}finally{button.disabled=false;}}
  function showFullHistory(serviceId){const service=findService(serviceId);if(!service)return;service.showAllEvents=!service.showAllEvents;renderDetail();}
  function closeOverlay(id){$(`#${id}`).classList.add('hidden');if(id==='cameraOverlay')stopCamera();if(id==='detailOverlay')pendingConfirmId=null;}
  function openDetail(id){selectedId=id;renderDetail();}
  function chooseServices(){return $$('.service-checks input:checked').map(input=>input.value);}
  function renderServiceInputs(preserve=true){const prior={};$$('.service-item-input', $('#serviceItemInputs')).forEach(row=>{const estimate=$('.service-estimate-input',row);prior[row.dataset.type]={title:$('.service-title-input',row).value,estimate:estimate.value,unit:$('.service-estimate-unit',row).value,edited:estimate.dataset.userEdited==='true'};});const selected=chooseServices();$('#serviceItemsField').classList.toggle('hidden',selected.length===0);$('#serviceItemInputs').innerHTML=selected.map(type=>{const suggestion=suggestEstimate(type,$('#requestInput').value),values=preserve&&prior[type]?prior[type]:{title:defaultTitles[type],estimate:(suggestion.minutes/60).toFixed(2).replace(/\.00$/,''),unit:'hours',edited:false};return `<div class="service-item-input" data-type="${type}"><span class="service-tag ${typeClass(type)}">${type}</span><input class="service-title-input" type="text" aria-label="${type} service item title" value="${esc(values.title)}" placeholder="Service item title" required><div class="estimate-input-group"><input class="service-estimate-input" type="number" min="0.01" step="any" aria-label="${type} estimated time" value="${esc(values.estimate)}" data-user-edited="${values.edited?'true':'false'}" placeholder="2" required><select class="service-estimate-unit" aria-label="${type} estimate unit"><option value="hours" ${values.unit==='hours'?'selected':''}>Hours</option><option value="minutes" ${values.unit==='minutes'?'selected':''}>Minutes</option><option value="days" ${values.unit==='days'?'selected':''}>Days</option></select></div><span class="service-estimate-mark">${suggestion.count?`based on ${suggestion.count} jobs`:'editable'}</span></div>`;}).join('');if(selected.length)applyHistoricalEstimates();}
  function applyHistoricalEstimates(){const description=$('#requestInput').value;let count=0;$$('.service-item-input', $('#serviceItemInputs')).forEach(row=>{const estimate=$('.service-estimate-input',row);if(estimate.dataset.userEdited==='true')return;const recommendation=suggestEstimate(row.dataset.type,description);estimate.value=(recommendation.minutes/60).toFixed(2).replace(/\.00$/,'');$('.service-estimate-unit',row).value='hours';if(recommendation.count)count+=recommendation.count;$('.service-estimate-mark',row).textContent=recommendation.count?`based on ${recommendation.count} jobs`:'editable';});if(count)$('#estimateNote').textContent=`Estimate references ${count} completed historical service record${count===1?'':'s'} of the same type. You can edit each estimate.`;else $('#estimateNote').textContent='Photo inspection is available above; service-time suggestions remain editable.';}
  function openIntake(){const form=$('#intakeForm');form.reset();delete form.dataset.summaryTitle;currentPhoto='';inspectionPhotos=[];pendingInspectionReport=null;$$('.service-checks input').forEach(input=>input.checked=false);renderServiceInputs(false);$('#vehicleSuggestions').innerHTML='';$('#vehicleSuggestions').classList.add('hidden');renderInspectionPhotos();renderInspectionPreview();$('#scanHint').textContent='Add up to four photos; choose a category before each photo.';$('#estimateNote').textContent='Photo inspection is available above; service-time suggestions remain editable.';$('#intakeOverlay').classList.remove('hidden');requestAnimationFrame(()=>$('#plateInput').focus());}
  function showVehicleSuggestions(value,showAll=false){const panel=$('#vehicleSuggestions'),query=value.trim().toLowerCase();if(!query&&!showAll){panel.innerHTML='';panel.classList.add('hidden');return;}const unique=new Map();for(const record of [...records].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))){const key=record.plate.trim().toUpperCase(),prior=unique.get(key);if(!prior||(overallStatus(prior)==='completed'&&overallStatus(record)!=='completed'))unique.set(key,record);}const matches=[...unique.values()].filter(record=>!query||[record.plate,record.customer].some(field=>(field||'').toLowerCase().includes(query))).slice(0,6);if(!matches.length){panel.innerHTML=`<div class="suggestion-empty">No matching vehicle found</div>`;panel.classList.remove('hidden');positionVehicleSuggestions(panel);return;}panel.innerHTML=`<span class="suggestion-heading">Existing vehicles</span>${matches.map(record=>`<button type="button" class="vehicle-suggestion" data-record-id="${esc(record.id)}" role="option"><span class="suggestion-plate">${esc(record.plate)}</span><span class="suggestion-customer">${esc(record.customer||'Customer not listed')}</span></button>`).join('')}`;panel.classList.remove('hidden');positionVehicleSuggestions(panel);}
  function positionVehicleSuggestions(panel){const grid=$('#intakeForm .form-grid'),anchor=document.activeElement?.closest('.field');if(!grid||!anchor)return;const gridRect=grid.getBoundingClientRect(),anchorRect=anchor.getBoundingClientRect();panel.style.top=`${anchorRect.bottom-gridRect.top+5}px`;panel.style.left=`${anchorRect.left-gridRect.left}px`;panel.style.width=`${anchorRect.width}px`;}
  function selectExistingVehicle(recordId){const record=records.find(item=>item.id===recordId);if(!record)return;$('#plateInput').value=record.plate;$('#vehicleInput').value=record.vehicle||'';$('#customerInput').value=record.customer||'';$('#phoneInput').value=record.phone||'';$('#emailInput').value=record.email||'';$('#vehicleSuggestions').classList.add('hidden');$('#vehicleSuggestions').innerHTML='';toast(`Loaded ${record.plate} from existing vehicle records`);}
  async function photoData(file){let bitmap=null,source,release=()=>{};try{if(window.createImageBitmap){bitmap=await createImageBitmap(file);source=bitmap;release=()=>bitmap.close();}}catch{}if(!source){const url=URL.createObjectURL(file);source=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('This image format is not supported by the browser.'));image.src=url;});release=()=>URL.revokeObjectURL(url);}const scale=Math.min(1,1280/Math.max(source.width,source.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(source.width*scale));canvas.height=Math.max(1,Math.round(source.height*scale));canvas.getContext('2d').drawImage(source,0,0,canvas.width,canvas.height);release();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.62));if(!blob)throw new Error('Could not prepare the vehicle photo.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});}
  async function loadOcr(){if(window.Tesseract)return window.Tesseract;if(!visionLibraryPromise)visionLibraryPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';script.onload=()=>resolve(window.Tesseract);script.onerror=()=>reject(new Error('Could not load the photo text reader.'));document.head.appendChild(script);});return visionLibraryPromise;}
  async function scanPlateFromPhoto(photo=currentPhoto,automatic=false){if(!photo){if(!automatic)toast('Take or upload a vehicle photo first');return;}const scanId=++plateScanGeneration,initialPlate=$('#plateInput').value.trim();if(automatic&&initialPlate)return;$('#scanPlateBtn').textContent='Reading…';$('#scanHint').textContent='Checking photo for a registration number…';try{const tesseract=await loadOcr();const result=await tesseract.recognize(photo,'eng');if(scanId!==plateScanGeneration)return;const text=String(result.data.text||'').toUpperCase().replace(/[^A-Z0-9\s]/g,' '),candidates=text.match(/\b[A-Z0-9]{5,8}\b/g)||[];const plate=candidates.find(value=>/[A-Z]/.test(value)&&/\d/.test(value));if(plate&&(!automatic||$('#plateInput').value.trim()===initialPlate)){$('#plateInput').value=plate;$('#scanHint').textContent=`Plate found: ${plate} · please verify`;if(!automatic)toast(`Plate detected: ${plate}`);}else if(plate){$('#scanHint').textContent='Registration entered manually. Please verify it against the photo.';}else{$('#scanHint').textContent='No clear plate found. Enter it manually or try a closer photo.';if(!automatic)toast('Could not read a plate. Try a closer photo.');}}catch(error){console.error(error);if(scanId===plateScanGeneration){$('#scanHint').textContent='Photo text reader could not load. Enter the plate manually.';if(!automatic)toast(error.message||'Photo reading failed');}}finally{if(scanId===plateScanGeneration)$('#scanPlateBtn').textContent='Scan photo';}}
