    $('#detailContent').addEventListener('click',async event=>{const vehicleLink=event.target.closest('#checkCustomerVehicles');if(vehicleLink){const record=selected();if(!record)return;const customer=record.customer||'';closeOverlay('detailOverlay');selectedId=null;activeFilter='all';$$('.filter').forEach(button=>button.classList.toggle('active',button.dataset.filter==='all'));$('#serviceFilter').value='all';$('#searchInput').value=customer;render();window.scrollTo({top:0,behavior:'smooth'});$('#searchInput').focus();return;}const copyButton=event.target.closest('.copy-staff-customer-code');if(!copyButton)return;if(await copyCode(copyButton.dataset.copyCode))copyButton.textContent='Copied';});
