    $$('[data-close]').forEach(button=>button.addEventListener('click',()=>closeOverlay(button.dataset.close)));$$('.overlay').forEach(overlay=>overlay.addEventListener('click',event=>{if(event.target===overlay)closeOverlay(overlay.id);}));
    $('#cameraBtn').addEventListener('click',()=>{if(matchMedia('(max-width: 760px)').matches){$('#photoFile').click();return;}startCamera();});$('#uploadBtn').addEventListener('click',()=>$('#photoFile').click());$('#photoFile').addEventListener('change',async event=>{const input=event.currentTarget,files=[...input.files],categories=['exterior','tyres','engine_bay','physical_damage'],start=Math.max(0,categories.indexOf($('#inspectionPhotoCategory').value));for(const [index,file] of files.slice(0,4).entries())await acceptPhoto(file,categories[(start+index)%categories.length]);if(files.length>4)toast('Choose up to four photos per report');input.value='';});$('#photoCapture').addEventListener('dragover',event=>{event.preventDefault();$('#photoCapture').classList.add('photo-drop-active');});$('#photoCapture').addEventListener('dragleave',event=>{if(!event.currentTarget.contains(event.relatedTarget))event.currentTarget.classList.remove('photo-drop-active');});$('#photoCapture').addEventListener('drop',async event=>{event.preventDefault();$('#photoCapture').classList.remove('photo-drop-active');const files=[...(event.dataTransfer?.files||[])].filter(file=>file.type.startsWith('image/')),categories=['exterior','tyres','engine_bay','physical_damage'],start=Math.max(0,categories.indexOf($('#inspectionPhotoCategory').value));for(const [index,file] of files.slice(0,4).entries())await acceptPhoto(file,categories[(start+index)%categories.length]);if(files.length>4)toast('Choose up to four photos per report');});document.addEventListener('paste',async event=>{if($('#intakeOverlay').classList.contains('hidden'))return;const files=[...(event.clipboardData?.items||[])].map(item=>item.kind==='file'?item.getAsFile():null).filter(file=>file?.type.startsWith('image/'));if(!files.length)return;event.preventDefault();const categories=['exterior','tyres','engine_bay','physical_damage'],start=Math.max(0,categories.indexOf($('#inspectionPhotoCategory').value));for(const [index,file] of files.slice(0,4).entries())await acceptPhoto(file,categories[(start+index)%categories.length]);});$('#photoPreview').addEventListener('click',event=>{const button=event.target.closest('.remove-inspection-photo');if(!button)return;inspectionPhotos.splice(Number(button.dataset.photoIndex),1);pendingInspectionReport=null;renderInspectionPhotos();renderInspectionPreview();$('#scanHint').textContent='Photo removed. Analyse again after you finish selecting photos.';});$('#analyzeInspectionBtn').addEventListener('click',analyzeInspection);$('#scanPlateBtn').addEventListener('click',()=>scanPlateFromPhoto(currentPhoto,false));$('#captureBtn').addEventListener('click',capturePhoto);$('#switchCameraBtn').addEventListener('click',switchCamera);
